import unittest,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).parents[1]/'scripts')); import validate
class StructureTests(unittest.TestCase):
 def test_validator(self): self.assertEqual(validate.main(),0)
 def test_catalog_validator(self):
  from pathlib import Path
  spec=__import__('importlib.util').util.spec_from_file_location('catalog',Path(validate.ROOT/'design-system/validate_catalog.py')); mod=__import__('importlib.util').util.module_from_spec(spec); spec.loader.exec_module(mod)
  self.assertEqual(mod.main(),0)
 def test_catalog_stylesheet_cache_version(self):
  index=(validate.ROOT/'design-system/index.html').read_text(); self.assertIn('href="catalog.css?v=40"',index); self.assertIn('href="bil-components.css?v=6"',index); self.assertIn('catalog.js?v=16',index)
 def test_pages_and_layouts(self):
  root=validate.ROOT; self.assertTrue(all((root/'design-system'/x).exists() for x in ['index.html','components.html','slides.html']))
  m=json.loads((root/'slide-templates/template-manifest.json').read_text()); self.assertEqual([x['id'] for x in m['layouts']],['title','title-media','regular']); media=[x for x in m['layouts'] if x['id']=='title-media'][0]; self.assertEqual(media['geometry']['title'],{'left':120,'top':54,'max_width':960}); self.assertEqual(media['geometry']['media'],{'left':370,'top':270,'width':1180,'height':660,'fit':'contain','radius':32})
 def test_no_project_decks_bundled(self): self.assertFalse((validate.ROOT/'slide-templates/reference-decks').exists())
 def test_exact_catalog_contract(self):
  root=validate.ROOT/'design-system'; data=json.loads((root/'components-manifest.json').read_text()); html=(root/'index.html').read_text(); self.assertEqual(len(data['components']),13); self.assertIn('buttons',data); self.assertEqual(html.count('data-motion='),3); self.assertEqual(html.count('data-component='),13); self.assertEqual(html.count('<h1'),1); self.assertIn('class="visually-hidden">BIG IDEAs Lab Design System</h1>',html); self.assertIn('<span>Design System</span>',html); self.assertNotIn('id="buttons"',html); self.assertNotIn('href="#buttons"',html); ids=['color','typography','assets','motion','components','slides']; self.assertEqual([html.index('id="'+x+'"') for x in ids],sorted(html.index('id="'+x+'"') for x in ids)); self.assertIn('<a aria-current="location" href="#color">Color</a>',html); self.assertIn('<strong>Display</strong><span>Source Serif 4</span>',html); self.assertIn('<strong>Interface</strong><span>Inter</span>',html); self.assertIn('<strong>Data</strong><span>IBM Plex Mono</span>',html); self.assertEqual(html.count('class="agent-example"'),6); self.assertIn('data-component="media-frame"',html); self.assertIn('assets/media/ppg-tissue-cutaway.jpg',html); self.assertEqual(html.count('data-copy-text='),12)
  self.assertEqual(html.count('assets/decor/bil-opening-sunburst-spectral-edge.png'),4); self.assertNotIn('opening-optical',html[html.index('data-layout="regular"'):html.index('</button>',html.index('data-layout="regular"'))]); self.assertNotIn('opening-optical',html[html.index('id="inspect-regular"'):html.index('</div>',html.index('id="inspect-regular"'))]); self.assertNotIn('bil-opening-ribbon.png',html); self.assertEqual(html[html.index('data-layout="title"'):html.index('</button>',html.index('data-layout="title"'))].count('black_duke_bigideaslab.png'),1)
 def test_v2_starters_and_previews(self):
  root=validate.ROOT; slides=(root/'design-system/index.html').read_text(); self.assertTrue(all(x in slides for x in ['data-layout="title"','data-layout="title-media"','data-layout="regular"'])); self.assertGreaterEqual(slides.count('slide-logo'),6)
 def test_title_media_catalog_stage_class(self):
   import re
   slides=(validate.ROOT/'design-system/index.html').read_text(); self.assertEqual(slides.count('class="thumb-stage slide-stage title-media"'),2); self.assertIn('id="inspect-title-media" class="thumb-stage slide-stage title-media"',slides)
   turners=re.findall(r'<nav class="slide-page-turner"[^>]*>.*?</nav>',slides,re.S)
   self.assertEqual(len(turners),6); self.assertTrue(all(t.count('<output')==1 for t in turners)); self.assertEqual(slides.count('aria-label="Slide 1 of 3"'),2); self.assertEqual(slides.count('aria-label="Slide 2 of 3"'),2); self.assertEqual(slides.count('aria-label="Slide 3 of 3"'),2); self.assertEqual(slides.count('aria-label="Media placeholder"'),2); self.assertEqual(slides.count('assets/icons/lucide-image.svg'),2)
   thumbs=re.findall(r'<button class="layout-option".*?</button>',slides,re.S); self.assertEqual(len(thumbs),3); self.assertTrue(all(t.count('<button')==1 and t.count('slide-page-turner-icon')==2 and t.count('<output')==1 for t in thumbs)); inspect=slides[slides.index('id="inspect-title"'):]; self.assertEqual(inspect.count('<button type="button" aria-label="Previous slide"'),3); self.assertEqual(inspect.count('<button type="button" aria-label="Next slide"'),3); self.assertEqual(inspect.count('<output'),3)
   css=(validate.ROOT/'design-system/catalog.css').read_text(); self.assertIn('title-media h3{position:absolute;left:120px;top:54px;max-width:960px;margin:0;font:600 60px/1.02 Inter,sans-serif;letter-spacing:-.03em',css); self.assertIn('title-media p{position:absolute;left:120px;top:196px',css); self.assertIn('.slide-stage.title-media .slide-media{left:370px;top:270px;width:1180px;height:660px',css); self.assertIn('object-fit:contain;background:#E5E7EB',css); self.assertIn('regular h3{position:absolute;left:120px;top:60px;max-width:960px;margin:0;font:600 60px/1.02 Inter,sans-serif;letter-spacing:-.03em',css); self.assertNotIn('.slide-stage.regular p',css); self.assertIn('title-opening h3{position:relative;left:auto;top:auto;max-width:none;margin:0;font-size:80px;line-height:1.08',css)
   regular=slides[slides.index('data-layout="regular"'):slides.index('id="inspect-title"')]; self.assertIn('Study overview',regular); self.assertNotIn('Presenter Name',regular); self.assertNotIn('Presentation Date',regular); self.assertNotIn('class="meta"',regular)
 def test_combined_template_media_and_page_turner_contract(self):
  combo=(validate.ROOT/'slide-templates/bil-lab-presentation-template.html').read_text(); self.assertNotIn('Title + Media',combo); self.assertNotIn('Title + media',combo); self.assertIn('Ideas that move<br>the world.',combo); self.assertIn('aria-label="Media placeholder"',combo); self.assertNotIn('<span>MEDIA</span>',combo); self.assertIn('background:#E5E7EB',combo); self.assertIn('width:96px;height:96px',combo); self.assertIn('height:56px',combo); self.assertIn('border-radius:999px',combo); self.assertIn('min-width:44px',combo); self.assertIn('data-page-turner-slide',combo); self.assertIn('ArrowLeft',combo); self.assertIn('ArrowRight',combo)
  self.assertIn('<h2 class="title">Study overview</h2><div class="main" data-slot="main"></div>',combo); regular=combo[combo.index('<section id="regular"'):]; self.assertNotIn('Presenter Name',regular); self.assertNotIn('Presentation Date',regular); self.assertNotIn('class="meta"',regular); self.assertNotIn('.regular .meta',combo)
 def test_title_gallery_geometry_and_title_media_unchanged(self):
  root=validate.ROOT; starter=(root/'slide-templates/starters/title.html').read_text(); combo=(root/'slide-templates/bil-lab-presentation-template.html').read_text(); media=(root/'slide-templates/starters/title-media.html').read_text()
  for text in (starter,combo):
   self.assertIn('Ideas that move<br>the world.',text); self.assertIn('Presenter Name',text); self.assertIn('Presentation Date',text); self.assertIn('data-slot="presenter"',starter); self.assertIn('data-slot="date"',starter); self.assertNotIn('data-slot="institution"',starter); self.assertIn('right:44px;top:39px;width:422px',text); self.assertIn('title-copy',text); self.assertIn('left:134px;top:378px',text); self.assertIn('max-width:672px',text); self.assertIn('margin:25px 0 0;width:1100px;max-width:1100px;white-space:nowrap',text); self.assertNotIn('top:620px',text); title_region=text[text.index('title-opening'):text.index('title-media')] if 'title-media' in text else text; self.assertNotIn('Presenter · Date',title_region); self.assertNotIn('108px',title_region); self.assertTrue('font-size:80px;line-height:1.08' in title_region or 'font:400 80px/1.08' in title_region)
  self.assertIn('right:44px;top:39px;width:422px',media); self.assertIn('left:370px;top:270px;width:1180px;height:660px',media); self.assertIn('object-fit:contain',media); self.assertNotIn('Presenter · Date',media); self.assertIn('Ideas that move',media)
  for text in (starter,combo,media,(root/'design-system/catalog.css').read_text()):
   self.assertNotIn('right:300px;top:72px;width:240px',text); self.assertNotIn('right:120px;top:72px;width:270px',text)
if __name__=='__main__': unittest.main()
